package cn.local.wenyan;
import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.view.*;
import android.widget.*;

/** Dimmable, back-dismissible bottom sheet. A canceled choice never writes a preference. */
final class PreferenceSheet extends Dialog {
 final MainActivity a;final LinearLayout body;private final LinearLayout panel;private boolean closing;private android.animation.ValueAnimator dimmer;
 PreferenceSheet(MainActivity a,String title){super(a);this.a=a;requestWindowFeature(Window.FEATURE_NO_TITLE);panel=new LinearLayout(a);panel.setOrientation(1);panel.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(18));panel.setBackground(a.bg(0xfff7f7f7,24));LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setBaselineAligned(false);TextView label=new TextView(a);label.setText(title);label.setTextSize(18);label.setIncludeFontPadding(false);label.setTextColor(0xff242424);label.setGravity(Gravity.CENTER);header.addView(label,new LinearLayout.LayoutParams(0,a.dp(56),1));Button close=a.action("",()->dismiss());close.setContentDescription("关闭"+title);close.setCompoundDrawablesWithIntrinsicBounds(new UiIcon(11,a.dp(22),0xff777777),null,null,null);header.addView(close,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));panel.addView(header);body=new LinearLayout(a);body.setOrientation(1);ScrollView scroll=new ScrollView(a){protected void onMeasure(int w,int h){super.onMeasure(w,MeasureSpec.makeMeasureSpec((int)(a.getResources().getDisplayMetrics().heightPixels*.60),MeasureSpec.AT_MOST));}};scroll.setFillViewport(false);scroll.addView(body);panel.addView(scroll);setContentView(panel);setCanceledOnTouchOutside(true);setOnKeyListener((dialog,key,event)->{if(key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)dismiss();return true;}return false;});final float[] start={0};header.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){start[0]=event.getRawY();return true;}if(event.getAction()==MotionEvent.ACTION_UP){if(event.getRawY()-start[0]>a.dp(60))dismiss();return true;}return true;});}
 void choice(String title,boolean selected,Runnable run){Button b=a.action(title+(selected?"  ✓":""),run);b.setTextColor(selected?0xffff7900:0xff242424);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(a.dp(18),0,a.dp(18),0);body.addView(b,new LinearLayout.LayoutParams(-1,a.dp(58)));}
 void note(String value){TextView t=new TextView(a);t.setText(value);t.setTextColor(0xff888888);t.setTextSize(13);t.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(14));body.addView(t);}
 void confirm(String title,Runnable run){Button button=a.action(title,run);button.setTextColor(Color.WHITE);button.setBackground(a.bg(0xffff7900,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,a.dp(52));p.topMargin=a.dp(14);panel.addView(button,p);}
 @Override public void onBackPressed(){dismiss();}
 void dim(float from,float to,long duration){if(dimmer!=null)dimmer.cancel();dimmer=android.animation.ValueAnimator.ofFloat(from,to);dimmer.setDuration(duration);dimmer.addUpdateListener(value->{Window w=getWindow();if(w!=null&&isShowing())w.setDimAmount((Float)value.getAnimatedValue());});dimmer.start();}
 void finishDismiss(){super.dismiss();if(a.activeSheet==this)a.activeSheet=null;}
 @Override public void dismiss(){if(closing)return;if(!isShowing()){finishDismiss();return;}closing=true;panel.animate().cancel();Window w=getWindow();dim(w==null?0:w.getAttributes().dimAmount,0,300);panel.animate().translationY(panel.getHeight()).alpha(.96f).setDuration(320).setInterpolator(new android.view.animation.PathInterpolator(.4f,0,1,1)).withEndAction(()->finishDismiss()).start();}
 @Override public void show(){a.activeSheet=this;closing=false;Window w=getWindow();w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setDimAmount(0);w.setGravity(Gravity.BOTTOM);w.setNavigationBarColor(0xfff7f7f7);w.setWindowAnimations(0);panel.setTranslationY(a.getResources().getDisplayMetrics().heightPixels);panel.setAlpha(.96f);super.show();w.setLayout(-1,-2);panel.getViewTreeObserver().addOnPreDrawListener(new android.view.ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){panel.getViewTreeObserver().removeOnPreDrawListener(this);if(closing||!isShowing())return true;panel.setTranslationY(panel.getHeight());panel.animate().translationY(0).alpha(1).setDuration(420).setInterpolator(new android.view.animation.PathInterpolator(.22f,.61f,.36f,1)).start();dim(0,.45f,320);return true;}});}
}
